static BOOL nativeDylib(NSString *path){NSData *d=[NSData dataWithContentsOfFile:path options:NSDataReadingMappedIfSafe error:NULL];if(d.length<sizeof(struct mach_header_64)||d.length>16*1024*1024)return NO;const uint8_t *bytes=d.bytes;uint32_t magic;memcpy(&magic,bytes,4);size_t offset=0,length=d.length;
