static NSArray *installed(void){NSString *base=folder(@"plugins");if(!base)return @[];NSMutableArray *items=[NSMutableArray array];for(NSString *name in [[NSFileManager.defaultManager contentsOfDirectoryAtPath:base error:NULL] sortedArrayUsingSelector:@selector(compare:)]){if([name hasPrefix:@"."])continue;NSString *path=[base stringByAppendingPathComponent:name];if(!ordinary(path,YES))continue;NSDictionary *m=manifest(path);if(m){NSMutableDictionary *item=[m mutableCopy];item[@"directory"]=name;[items addObject:item];}}return items;}
