NSString *loader_plugin_manager_error_message(NSString *code){NSDictionary *messages=@{@"PLUGIN_DOWNLOAD_FAILED":@"下载未完成，请检查网络后重试。",@"PLUGIN_HTTP_FAILED":@"插件源暂时不可用。",@"PLUGIN_DIRECT_URL_REQUIRED":@"插件源需要提供直接下载链接。",@"PLUGIN_HASH_MISMATCH":@"插件包校验失败，未安装。",@"PLUGIN_METADATA_INVALID":@"插件发布信息格式不正确。",@"PLUGIN_SOURCE_INVALID":@"请输入有效的 HTTPS 发布信息链接。",@"PACKAGE_IDENTITY_MISMATCH":@"下载包与发布的插件或版本不一致。",@"BUILTIN_REQUIRES_LOADER_UPDATE":@"内置插件请随 Loader 一起更新。",@"PLUGIN_VERSION_NOT_NEWER":@"已有相同或更新的插件版本。",@"PLUGIN_UPDATE_ALREADY_PENDING":@"已有待安装版本，请先重新启动。",@"PLUGIN_MANAGER_BUSY":@"正在处理插件，请稍后重试。",@"PLUGIN_LIMIT_REACHED":@"已达到当前插件数量上限。",@"PACKAGE_PATH_REJECTED":@"插件包包含不允许的文件路径或链接。",@"PACKAGE_MANIFEST_INVALID":@"插件包格式或当前平台不兼容。",@"PLUGIN_STORAGE_UNAVAILABLE":@"插件数据目录不可写。"};return messages[code]?:@"操作未完成，请检查插件包和数据目录。";}
